// Hand-authored office-open XLSX templates. Unlike DOC_TEMPLATES/PPT_TEMPLATES
// (generated by parsing pre-made .docx/.pptx files — see
// scripts/generate-office-templates.mjs), there is no source spreadsheet
// design to parse, so these are written directly against the office-open
// WorkbookOptions JSON shape. Brand colors are baked in using the "slate"
// color scheme's hex values and registered in office_template_roles.ts
// (XLSX_TEMPLATE_ROLES) so `recolor` can swap them for any other scheme.
// Cells that should be filled in follow the same `[Placeholder]` convention
// as the docx/pptx templates.

const PRIMARY = "0B2545";
const PRIMARY_TEXT = "FFFFFF";
const SURFACE = "F2F4F7";
const MUTED = "5B6570";
const BORDER = "C7CDD3";

const headerStyle = {
  font: { bold: true, color: PRIMARY_TEXT, size: 10 },
  fill: { type: "solid", color: PRIMARY },
  alignment: { vertical: "center" },
};
const subHeaderStyle = {
  font: { bold: true, color: PRIMARY, size: 10 },
  fill: { type: "solid", color: SURFACE },
  border: { bottom: { style: "thin", color: BORDER } },
};
const labelStyle = { font: { bold: true, color: MUTED, size: 9 } };
const mutedStyle = { font: { color: MUTED, italic: true, size: 9 } };
const totalStyle = {
  font: { bold: true, color: PRIMARY, size: 10 },
  fill: { type: "solid", color: SURFACE },
  border: { top: { style: "thin", color: BORDER } },
};
const cellBorderStyle = { border: { bottom: { style: "thin", color: BORDER } } };
const currency = "$#,##0.00";
const percent = "0.0%";
const titleStyle = { font: { bold: true, color: PRIMARY, size: 16 } };
const subtitleStyle = { font: { color: MUTED, italic: true, size: 10 } };

function cell(value: string | number | boolean | null, style?: Record<string, unknown>) {
  return style ? { value, style } : { value };
}
function row(cells: unknown[], height?: number) {
  return height ? { cells, height } : { cells };
}
function headerRow(labels: string[]) {
  return row(labels.map((l) => cell(l, headerStyle)));
}
function dataRow(values: (string | number)[], styles?: (Record<string, unknown> | undefined)[]) {
  return row(values.map((v, i) => cell(v, { ...cellBorderStyle, ...styles?.[i] })));
}
function cols(widths: number[]) {
  return widths.map((width, i) => ({ min: i + 1, max: i + 1, width }));
}

const budgetTracker = {
  title: "Budget Tracker",
  worksheets: [
    {
      name: "Budget",
      columns: cols([26, 16, 16, 16, 24]),
      rows: [
        row([cell("[Company / Team Name] — Budget Tracker", titleStyle)]),
        row([cell("[Fiscal Year / Period]", subtitleStyle)]),
        row([cell("")]),
        headerRow(["Category", "Budgeted", "Actual", "Variance", "Notes"]),
        dataRow(["[Category one]", 5000, 4650, 350, "[Notes]"], [
          undefined,
          { numFmt: currency },
          { numFmt: currency },
          { numFmt: currency },
        ]),
        dataRow(["[Category two]", 3000, 3400, -400, "[Notes]"], [
          undefined,
          { numFmt: currency },
          { numFmt: currency },
          { numFmt: currency },
        ]),
        dataRow(["[Category three]", 2000, 1800, 200, "[Notes]"], [
          undefined,
          { numFmt: currency },
          { numFmt: currency },
          { numFmt: currency },
        ]),
        row([
          cell("Total", totalStyle),
          cell(10000, { ...totalStyle, numFmt: currency, formula: "SUM(B5:B7)" }),
          cell(9850, { ...totalStyle, numFmt: currency, formula: "SUM(C5:C7)" }),
          cell(150, { ...totalStyle, numFmt: currency, formula: "SUM(D5:D7)" }),
          cell("", totalStyle),
        ]),
      ],
    },
  ],
};

