const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

const timesheetTemplate = {
  title: "Timesheet",
  worksheets: [
    {
      name: "Timesheet",
      columns: cols([26, ...DAYS.map(() => 9), 12]),
      rows: [
        row([cell("Weekly Timesheet", titleStyle)]),
        row([cell("[Employee Name] — Week of [Date]", subtitleStyle)]),
        row([cell("")]),
        headerRow(["Task / Project", ...DAYS, "Total"]),
        dataRow(["[Task / project one]", 8, 8, 8, 8, 8, 0, 0, 40], [
          undefined,
          ...DAYS.map(() => undefined),
          { numFmt: "0.0", formula: "SUM(B5:H5)" },
        ]),
        dataRow(["[Task / project two]", 0, 0, 0, 0, 0, 0, 0, 0], [
          undefined,
          ...DAYS.map(() => undefined),
          { numFmt: "0.0", formula: "SUM(B6:H6)" },
        ]),
        row([
          cell("Total", totalStyle),
          ...DAYS.map((_, i) =>
            cell(8, { ...totalStyle, numFmt: "0.0", formula: `SUM(${String.fromCharCode(66 + i)}5:${String.fromCharCode(66 + i)}6)` }),
          ),
          cell(40, { ...totalStyle, numFmt: "0.0", formula: "SUM(I5:I6)" }),
        ]),
      ],
    },
  ],
};

export const XLSX_TEMPLATES: Record<string, { title: string; worksheets: unknown[] }> = {
  budget_tracker: budgetTracker,
  invoice_workbook_template: invoiceTemplate,
  project_tracker: projectTracker,
  expense_report: expenseReport,
  timesheet_template: timesheetTemplate,
};
